package com.harvestflow.registration.crypto;
import jakarta.persistence.AttributeConverter; import jakarta.persistence.Converter; import javax.crypto.Cipher; import javax.crypto.spec.GCMParameterSpec; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.security.SecureRandom; import java.util.Base64;
@Converter
public class EncryptedStringConverter implements AttributeConverter<String,String> {
 private static final String ALGO="AES/GCM/NoPadding"; private static final int IV=12;
 public String convertToDatabaseColumn(String value){if(value==null)return null;try{byte[] key=key();byte[] iv=new byte[IV];new SecureRandom().nextBytes(iv);Cipher c=Cipher.getInstance(ALGO);c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,iv));byte[] ct=c.doFinal(value.getBytes(StandardCharsets.UTF_8));byte[] out=new byte[IV+ct.length];System.arraycopy(iv,0,out,0,IV);System.arraycopy(ct,0,out,IV,ct.length);return Base64.getEncoder().encodeToString(out);}catch(Exception e){throw new IllegalStateException("Aadhaar encryption failed",e);}}
 public String convertToEntityAttribute(String value){if(value==null)return null;try{byte[] all=Base64.getDecoder().decode(value),iv=new byte[IV];System.arraycopy(all,0,iv,0,IV);byte[] ct=new byte[all.length-IV];System.arraycopy(all,IV,ct,0,ct.length);Cipher c=Cipher.getInstance(ALGO);c.init(Cipher.DECRYPT_MODE,new SecretKeySpec(key(),"AES"),new GCMParameterSpec(128,iv));return new String(c.doFinal(ct),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("Aadhaar decryption failed",e);}}
 private byte[] key(){String v=System.getenv("HARVESTFLOW_AADHAAR_ENCRYPTION_KEY");if(v==null||v.isBlank()){v="SGFydmVzdEZsb3dEZXZBYWRoYWFyS2V5MzJCeXRlcyE=";}byte[] k=Base64.getDecoder().decode(v);if(k.length!=32)throw new IllegalStateException("HARVESTFLOW_AADHAAR_ENCRYPTION_KEY must decode to 32 bytes");return k;}
}
